import json
import ast
from collections import defaultdict

def perceive(observation_history: list[str]) -> str:
    """
    Parse the current raw observation from the last element of observation_history.
    Output a concise (<2000 char) text summary of decision-relevant features.
    Never raises, never returns empty.
    """
    if not observation_history:
        return "empty_history"

    obs = observation_history[-1]

    # ----- helper: palette for integer grids -----
    int_palette = {
        0: "black", 1: "blue", 2: "red", 3: "green", 4: "yellow",
        5: "light-gray", 6: "magenta", 7: "orange", 8: "light-blue",
        9: "maroon", 10: "white", 11: "dark-gray"
    }

    def summarize_grid(grid, background, agent_color, agent_name, name_map=None):
        """
        grid: list of lists (strings or ints)
        background: value/string treated as background
        agent_color: value/string that marks the agent
        agent_name: string to describe agent in output
        name_map: optional dict to convert values to names (for int grids)
        """
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0

        agent_pos = None
        other_cells = []  # list of (r, c, color_name)

        for r in range(rows):
            row = grid[r]
            if len(row) != cols:
                # malformed row, skip
                continue
            for c in range(cols):
                cell = row[c]
                if cell == background:
                    continue
                # check agent
                if cell == agent_color:
                    agent_pos = (r, c)
                else:
                    # colour name
                    if name_map:
                        color_name = name_map.get(cell, f"code_{cell}")
                    else:
                        color_name = cell
                    other_cells.append((r, c, color_name))

        # Build summary
        parts = []
        if agent_pos is not None:
            parts.append(f"{agent_name} at ({agent_pos[0]},{agent_pos[1]})")
        else:
            parts.append("no_agent_found")

        # Add other non-background cells (limit to 1500 chars to leave room)
        if other_cells:
            # group by colour to compress
            color_groups = defaultdict(list)
            for r, c, col in other_cells:
                color_groups[col].append((r, c))
            cell_strs = []
            for col in sorted(color_groups.keys()):
                positions = color_groups[col]
                # Show up to 20 positions per colour
                coord_str = ",".join(f"({r},{c})" for r, c in positions[:20])
                if len(positions) > 20:
                    coord_str += f"...({len(positions)} total)"
                cell_strs.append(f"{col}:{coord_str}")
            # join all, truncate if necessary
            other_str = "; ".join(cell_strs)
            # ensure total string length < 2000
            if len(parts[0]) + len(other_str) > 1800:
                other_str = other_str[:1700] + "..."  # rough truncation
            parts.append(other_str)

        return "; ".join(parts)

    # ----- Try Autumn JSON grid -----
    try:
        start = obs.find("[[")
        end = obs.rfind("]]") + 2
        if start != -1 and end > start:
            grid_str = obs[start:end]
            grid = json.loads(grid_str)  # list of lists of strings
            if not grid:
                return "empty_grid_json"
            # Determine background: most common cell? Assume 'black'
            background = "black"
            agent_color = "orange"
            agent_name = "Agent"
            result = summarize_grid(grid, background, agent_color, agent_name)
            # Ensure non-empty
            if result.strip():
                return result
            else:
                return "grid_json_no_features"
    except Exception:
        pass

    # ----- Try ARC integer grid -----
    try:
        lines = obs.splitlines()
        grid_lines = []
        in_grid = False
        for line in lines:
            stripped = line.strip()
            if stripped.startswith("<grid_"):
                in_grid = True
                continue
            if in_grid:
                # stop at next marker or separator
                if stripped.startswith("<grid_") or stripped.startswith("====="):
                    break
                # collect lines that look like integer lists
                if stripped.startswith("[") and stripped.endswith("]"):
                    grid_lines.append(stripped)
        if grid_lines:
            grid = []
            for line in grid_lines:
                try:
                    row = ast.literal_eval(line)  # safe for ints
                    if isinstance(row, list):
                        grid.append(row)
                except Exception:
                    continue
            if grid:
                background = 0
                agent_color = 7
                agent_name = "Agent"
                # Use name_map to convert int codes to colour names
                name_map = int_palette
                result = summarize_grid(grid, background, agent_color, agent_name, name_map)
                if result.strip():
                    return result
                else:
                    return "int_grid_no_features"
    except Exception:
        pass

    # ----- Fallback: best-effort -----
    # If all parsing fails, return a non-empty string describing the situation
    return "parse_fallback_no_grid_detected"

import json
import sys
import re

# Define the environment rules that are constant across all episodes.
# These are distilled from the feedback to help the predictor infer actions.
RULES = (
    "rules: scroll=+1row; left->notrail; right,up,down,noop->trail1; "
    "left->5col-1; right->5col+1; up->5conv2; noop->5stay; "
    "wrap(bottom&noop)->(1,col+1); spawn(noagent&up)->(1,2)&5conv2"
)

def _parse_grid(obs: str):
    """Parse the observation string into a 2D list of integers.
    Handles both integer-grid (ARC) and JSON-string-grid (Autumn) formats.
    Returns (grid, success), where grid is list of lists of ints, success bool.
    """
    lines = obs.split('\n')
    # Locate the start of the direct observation
    start_idx = 0
    for i, line in enumerate(lines):
        if 'Start of Direct Observation' in line:
            start_idx = i + 1
            break
    while start_idx < len(lines) and lines[start_idx].strip() == '':
        start_idx += 1

    if start_idx >= len(lines):
        return [], False

    first_line = lines[start_idx].strip()

    # Detect JSON string-grid format (starts with "[[")
    if first_line.startswith('[['):
        try:
            s = obs.index('[[')
            e = obs.rindex(']]') + 2
            grid_str = obs[s:e]
            grid_list = json.loads(grid_str)
            color_map = {
                'black': 0, 'blue': 1, 'red': 2, 'green': 3, 'gold': 4,
                'gray': 5, 'lightgray': 5, 'magenta': 6, 'orange': 7,
                'lightblue': 8, 'darkred': 9, 'maroon': 9, 'white': 10,
                'darkgray': 11, 'darkgreen': 3
            }
            int_grid = []
            for row in grid_list:
                int_row = []
                for cell in row:
                    if isinstance(cell, str):
                        key = cell.strip().lower()
                        int_row.append(color_map.get(key, 0))
                    elif isinstance(cell, int):
                        int_row.append(cell)
                    else:
                        int_row.append(0)
                int_grid.append(int_row)
            return int_grid, True
        except Exception:
            return [], False
    else:
        # Integer grid format: find '<grid_0>' marker
        grid_start = None
        for idx, line in enumerate(lines[start_idx:], start=start_idx):
            if '<grid_' in line:
                grid_start = idx + 1
                break
        if grid_start is None:
            return [], False
        rows = []
        for line in lines[grid_start:]:
            stripped = line.strip()
            if not stripped.startswith('['):
                break
            try:
                row_list = json.loads(stripped)
                if not isinstance(row_list, list):
                    break
                rows.append([int(x) for x in row_list])
            except Exception:
                inner = stripped.strip('[]')
                if not inner.strip():
                    break
                parts = inner.split(',')
                try:
                    row_list = [int(p.strip()) for p in parts]
                    rows.append(row_list)
                except Exception:
                    break
        if rows:
            return rows, True
        else:
            return [], False


def perceive(observation_history):
    """
    Returns a concise text summary of decision-relevant features.
    The output must change between consecutive states to allow action recovery.
    """
    raw = observation_history[-1]
    grid, success = _parse_grid(raw)
    if not success or not grid:
        return "grid: empty; rules: " + RULES  # Never empty

    h = len(grid)
    w = len(grid[0]) if h > 0 else 0
    if h == 0 or w == 0:
        return "grid: empty; rules: " + RULES

    # Collect non‑black cells and locate the agent (color 7)
    non_black = []
    agent_pos = None
    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            if val != 0:
                non_black.append((r, c, val))
                if val == 7:
                    agent_pos = (r, c)

    # Compute derived flags that make action effects explicit
    bottom_row = h - 1
    type5_pos = None   # position of the only type‑5 cell (assume at most one)
    for (r, c, v) in non_black:
        if v == 5:
            type5_pos = (r, c)
            break

    # Flags
    agent_on_bottom = agent_pos is not None and agent_pos[0] == bottom_row
    type5_adjacent_right = False
    if agent_pos and type5_pos:
        if type5_pos[0] == agent_pos[0] and type5_pos[1] == agent_pos[1] + 1:
            type5_adjacent_right = True
    no_agent = agent_pos is None

    # Build the output string
    parts = []
    parts.append(RULES)
    parts.append(f"h={h} w={w}")
    if agent_pos:
        parts.append(f"agent=({agent_pos[0]},{agent_pos[1]})")
    else:
        parts.append("agent=None")
    # Flags
    flags = []
    if agent_on_bottom:
        flags.append("bottom")
    if type5_adjacent_right:
        flags.append("5adj_right")
    if no_agent:
        flags.append("noagent")
    if flags:
        parts.append("flags=" + ",".join(flags))

    # List all non‑black cells (sorted for consistency)
    # To keep output concise, limit the number of cells (but grid is small in practice)
    MAX_CELLS = 200
    if len(non_black) <= MAX_CELLS:
        cells_str = ";".join([f"({r},{c},{v})" for (r,c,v) in non_black])
    else:
        sample = non_black[:MAX_CELLS]
        cells_str = f"count={len(non_black)};sample=" + ";".join([f"({r},{c},{v})" for (r,c,v) in sample])
    parts.append("cells=[" + cells_str + "]")

    out = "; ".join(parts)
    if len(out) == 0:
        out = "empty_state"
    if len(out) > 2000:
        out = out[:1997] + "..."
    return out

import json
import re
import sys

# ----------------------------------------------------------------------
# Helper: parse the observation string into a 2D integer grid.
# Handles both ARC (integer grid) and Autumn (JSON colour names) formats.
# Returns (grid, success) where grid is list of list of ints.
# ----------------------------------------------------------------------
def _parse_grid(obs: str):
    lines = obs.split('\n')
    # Locate the "Start of Direct Observation" marker
    start_idx = 0
    for i, line in enumerate(lines):
        if 'Start of Direct Observation' in line:
            start_idx = i + 1
            break
    # Skip empty lines
    while start_idx < len(lines) and lines[start_idx].strip() == '':
        start_idx += 1

    if start_idx >= len(lines):
        return [], False

    first_line = lines[start_idx].strip()

    # ---- JSON colour-name format (Autumn) ----
    if first_line.startswith('[['):
        try:
            s = obs.index('[[')
            e = obs.rindex(']]') + 2
            grid_list = json.loads(obs[s:e])
            # Map colour names to integers
            color_map = {
                'black': 0, 'blue': 1, 'red': 2, 'green': 3, 'gold': 4,
                'gray': 5, 'lightgray': 5, 'magenta': 6, 'orange': 7,
                'lightblue': 8, 'darkred': 9, 'maroon': 9, 'white': 10,
                'darkgray': 11, 'darkgreen': 3
            }
            int_grid = []
            for row in grid_list:
                int_row = []
                for cell in row:
                    if isinstance(cell, str):
                        key = cell.strip().lower()
                        int_row.append(color_map.get(key, 0))
                    elif isinstance(cell, int):
                        int_row.append(cell)
                    else:
                        int_row.append(0)
                int_grid.append(int_row)
            return int_grid, True
        except Exception:
            return [], False

    # ---- Integer grid format (ARC) ----
    # Find the <grid_0> marker
    grid_start = None
    for idx, line in enumerate(lines[start_idx:], start=start_idx):
        if '<grid_' in line:
            grid_start = idx + 1
            break
    if grid_start is None:
        return [], False

    rows = []
    for line in lines[grid_start:]:
        stripped = line.strip()
        if not stripped.startswith('['):
            break
        # Try JSON parse first (works for [int, int, ...])
        try:
            row_list = json.loads(stripped)
            if not isinstance(row_list, list):
                break
            rows.append([int(x) for x in row_list])
        except Exception:
            # Manual fallback: remove brackets and split by commas
            inner = stripped.strip('[]')
            if not inner.strip():
                break
            parts = inner.split(',')
            try:
                row_list = [int(p.strip()) for p in parts]
                rows.append(row_list)
            except Exception:
                break
    if rows:
        return rows, True
    else:
        return [], False


# ----------------------------------------------------------------------
# Helper: map an integer colour code (0..11) to a single hex digit.
# Values outside 0..15 are mapped to 'f'.
# ----------------------------------------------------------------------
def _int_to_hex(val):
    if 0 <= val <= 15:
        return "0123456789abcdef"[val]
    else:
        return 'f'


# ----------------------------------------------------------------------
# Main function
# ----------------------------------------------------------------------
def perceive(observation_history):
    """
    Returns a concise text summary of decision-relevant features.
    For small grids (≤32×32) outputs the full grid in a compact hex encoding.
    For larger grids falls back to a structured summary with semantic labels.
    """
    raw = observation_history[-1]
    grid, success = _parse_grid(raw)
    if not success or not grid:
        return "grid: empty"

    h = len(grid)
    w = len(grid[0]) if h > 0 else 0
    if h == 0 or w == 0:
        return "grid: empty"

    # ---- Compact full‑grid output for manageable sizes ----
    # 2000 char limit; we reserve 10 chars for prefix and safety.
    # Full grid: h * (w+1) for hex chars plus pipe separators + 5 for "grid="
    estimated_len = h * (w + 1) + 5
    if estimated_len <= 1990:
        # Convert each row to a hex string and join with '|'
        rows_hex = []
        for r in range(h):
            row_hex = ''.join(_int_to_hex(grid[r][c]) for c in range(w))
            rows_hex.append(row_hex)
        grid_str = '|'.join(rows_hex)
        out = f"grid={grid_str}"
        if len(out) < 2000:
            return out
        # Fall through if length exceeds (unlikely, but safe)

    # ---- Fallback: structured semantic summary for larger grids ----
    # Identify special cells
    agent_pos = None          # value 7
    pad_pos = None            # bottom row, value 5 or 2 (pad)
    red_movers = []           # value 2 cells NOT on bottom row (moving object)
    blue_cells = []           # value 1
    other_cells = []          # any other non‑black, non‑special

    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            if val == 0:
                continue
            if val == 7:
                agent_pos = (r, c)
            elif val == 5 or (val == 2 and r == h-1):
                # Pad at bottom row
                pad_pos = (r, c, val)
            elif val == 2 and r != h-1:
                red_movers.append((r, c, val))
            elif val == 1:
                blue_cells.append((r, c, val))
            else:
                other_cells.append((r, c, val))

    parts = []
    if agent_pos is not None:
        parts.append(f"agent=({agent_pos[0]},{agent_pos[1]})")
    else:
        parts.append("agent=None")

    if pad_pos is not None:
        state = "active" if pad_pos[2] == 5 else "used"
        parts.append(f"pad=({pad_pos[0]},{pad_pos[1]}) {state}")
    else:
        parts.append("pad=None")

    # Red movers (max 5 reported to keep output short)
    if red_movers:
        rm_str = ';'.join(f"({r},{c},{v})" for (r,c,v) in red_movers[:5])
        if len(red_movers) > 5:
            rm_str += f"... (+{len(red_movers)-5} more)"
        parts.append(f"red_movers=[{rm_str}]")
    else:
        parts.append("red_movers=[]")

    # Blue pattern cells (report a sample if too many)
    MAX_BLUE = 30
    if blue_cells:
        if len(blue_cells) <= MAX_BLUE:
            bl_str = ';'.join(f"({r},{c},{v})" for (r,c,v) in blue_cells)
        else:
            sample = blue_cells[:MAX_BLUE]
            bl_str = ';'.join(f"({r},{c},{v})" for (r,c,v) in sample)
            bl_str += f"... (+{len(blue_cells)-MAX_BLUE} more)"
        parts.append(f"blue=[{bl_str}]")
    else:
        parts.append("blue=[]")

    # Other non‑black cells (limit to 20)
    if other_cells:
        oth = other_cells[:20]
        oth_str = ';'.join(f"({r},{c},{v})" for (r,c,v) in oth)
        if len(other_cells) > 20:
            oth_str += f"... (+{len(other_cells)-20} more)"
        parts.append(f"other=[{oth_str}]")
    else:
        parts.append("other=[]")

    out = "; ".join(parts)
    if len(out) == 0:
        out = "empty_state"
    elif len(out) > 2000:
        out = out[:1997] + "..."
    return out

import json
import ast
from collections import defaultdict

def perceive(observation_history: list[str]) -> str:
    """
    Parse the current raw observation from the last element of observation_history.
    Output a concise (<2000 char) summary of decision-relevant features,
    including explicit rules for the grid's dynamics.
    Never raises, never returns empty.
    """
    if not observation_history:
        return "empty_history"

    obs = observation_history[-1]

    # ----- Helper: palette for integer grids -----
    # We map both light-gray (5) and dark-gray (11) to "gray" for simplicity.
    int_to_name = {
        0: "black", 1: "blue", 2: "red", 3: "green", 4: "yellow",
        5: "gray", 6: "magenta", 7: "orange", 8: "lightblue",
        9: "maroon", 10: "white", 11: "gray"
    }

    def extract_state(grid):
        """
        grid: list of lists (cells are either int codes or colour-name strings).
        Returns a compact summary string.
        """
        rows = len(grid)
        cols = len(grid[0]) if rows else 0

        # Convert every cell to a standard colour name string.
        # For int grids, use int_to_name; for JSON grids, cells are already strings.
        def cell_name(cell):
            if isinstance(cell, int):
                return int_to_name.get(cell, f"unknown_{cell}")
            return cell.lower()

        agent_pos = None
        blue_positions = []
        gray_positions = []
        red_positions = []

        for r in range(rows):
            row = grid[r]
            if len(row) != cols:
                continue
            for c in range(cols):
                colour = cell_name(row[c])
                if colour == "orange":
                    agent_pos = (r, c)
                elif colour == "blue":
                    blue_positions.append((r, c))
                elif colour == "gray":
                    gray_positions.append((r, c))
                elif colour == "red":
                    red_positions.append((r, c))
                # ignore other colours (black background, green, yellow, etc.)

        # ----- Determine blue phase -----
        blue_phase = -1
        if blue_positions:
            # The blue pattern uses two column sets:
            # phase 0: columns that are 1 mod 3 (1,4,7,10,13)
            # phase 1: columns that are 2 mod 3 (2,5,8,11,14)
            sample_col = blue_positions[0][1]
            if sample_col % 3 == 1:
                blue_phase = 0
            elif sample_col % 3 == 2:
                blue_phase = 1
            # otherwise leave as -1 (shouldn't happen in this environment)

        # ----- Agent at bottom? -----
        at_bottom = False
        if agent_pos is not None:
            at_bottom = (agent_pos[0] == rows - 1)

        # ----- Build output string (<2000 chars) -----
        # Static rules that govern all transitions (deterministic for this environment)
        rules = (f"rules:grid{rows}x{cols},autoRow+1,red-1,bluePhaseFlip,"
                 "left/right:grayCol-/+1,up:wrap+gray2red")

        parts = [rules]

        # Agent
        if agent_pos is not None:
            parts.append(f"agent:({agent_pos[0]},{agent_pos[1]})")
        else:
            parts.append("agent:none")

        # Blue phase
        if blue_phase != -1:
            parts.append(f"bluePhase:{blue_phase}")
        else:
            parts.append("bluePhase:none")

        # Gray (expect at most one)
        if len(gray_positions) == 1:
            g = gray_positions[0]
            parts.append(f"gray:({g[0]},{g[1]})")
        elif len(gray_positions) > 1:
            # Very unlikely, but list them
            coords = ",".join(f"({r},{c})" for r, c in gray_positions)
            parts.append(f"gray:{coords}")
        else:
            parts.append("gray:none")

        # Red (expect at most one, but allow multiple)
        if len(red_positions) == 1:
            rp = red_positions[0]
            parts.append(f"red:({rp[0]},{rp[1]})")
        elif len(red_positions) > 1:
            coords = ",".join(f"({r},{c})" for r, c in red_positions)
            parts.append(f"red:{coords}")
        else:
            parts.append("red:none")

        parts.append(f"atBottom:{'true' if at_bottom else 'false'}")

        return "; ".join(parts)

    # ----- Try Autumn JSON grid (2D array of strings) -----
    try:
        start = obs.find("[[")
        end = obs.rfind("]]") + 2
        if start != -1 and end > start:
            grid_str = obs[start:end]
            grid = json.loads(grid_str)
            if grid and len(grid) > 0 and len(grid[0]) > 0:
                result = extract_state(grid)
                if result.strip():
                    return result
    except Exception:
        pass

    # ----- Try ARC integer grid -----
    try:
        lines = obs.splitlines()
        grid_lines = []
        in_grid = False
        for line in lines:
            stripped = line.strip()
            if stripped.startswith("<grid_"):
                in_grid = True
                continue
            if in_grid:
                if stripped.startswith("<grid_") or stripped.startswith("====="):
                    break
                if stripped.startswith("[") and stripped.endswith("]"):
                    grid_lines.append(stripped)
        if grid_lines:
            grid = []
            for line in grid_lines:
                try:
                    row = ast.literal_eval(line)
                    if isinstance(row, list):
                        grid.append(row)
                except Exception:
                    continue
            if grid:
                result = extract_state(grid)
                if result.strip():
                    return result
    except Exception:
        pass

    # ----- Fallback (should never trigger if observation is valid) -----
    return "parse_fallback_no_grid_detected"

