        # Static rules that govern all transitions (deterministic for this environment)
        rules = (f"rules:grid{rows}x{cols},autoRow+1,red-1,bluePhaseFlip,"
                 "left/right:grayCol-/+1,up:wrap+gray2red")

        parts = [rules]

