        if agent_pos is not None:
            parts.append(f"agent:({agent_pos[0]},{agent_pos[1]})")
        else:
            parts.append("agent:none")

        # Blue phase
        if blue_phase != -1:
            parts.append(f"bluePhase:{blue_phase}")
        else:
            parts.append("bluePhase:none")

        # Gray (expect at most one)
