        else:
            parts.append("gray:none")

        # Red (expect at most one, but allow multiple)
        if len(red_positions) == 1:
            rp = red_positions[0]
            parts.append(f"red:({rp[0]},{rp[1]})")
        elif len(red_positions) > 1:
