import json
import ast
from collections import defaultdict

def perceive(observation_history: list[str]) -> str:
    """
    Parse the current raw observation from the last element of observation_history.
    Output a concise (<2000 char) summary of decision-relevant features, including
    the action (or set of possible actions) that led to the current state,
    so that the action is recoverable from two consecutive outputs.
    Never raises, never returns empty.
    """
    if not observation_history:
        return "empty_history"

    obs_current = observation_history[-1]

    # ----- Helper: palette for integer grids -----
    int_to_name = {
        0: "black", 1: "blue", 2: "red", 3: "green", 4: "yellow",
        5: "gray", 6: "magenta", 7: "orange", 8: "lightblue",
        9: "maroon", 10: "white", 11: "gray"
    }

    # ----- Extract step number (if present) -----
    def extract_step(obs):
        for line in obs.splitlines():
            line = line.strip()
            if line.startswith("Step:"):
                try:
                    return int(line.split(":")[1].strip())
                except:
                    pass
            if line.startswith("Action count:"):
                try:
                    return int(line.split(":")[1].strip())
                except:
                    pass
        return None

    step_str = f"step:{extract_step(obs_current)}" if extract_step(obs_current) is not None else "step:unknown"

    # ----- Parse grid from observation -----
    def parse_grid(obs):
        # Try Autumn JSON grid
        try:
            start = obs.find("[[")
            end = obs.rfind("]]") + 2
            if start != -1 and end > start:
                grid_str = obs[start:end]
                grid = json.loads(grid_str)
                if grid and len(grid) > 0 and len(grid[0]) > 0:
                    return grid
        except:
            pass

        # Try ARC integer grid
        try:
            lines = obs.splitlines()
            grid_lines = []
            in_grid = False
            for line in lines:
                stripped = line.strip()
                if stripped.startswith("<grid_"):
                    in_grid = True
                    continue
                if in_grid:
                    if stripped.startswith("<grid_") or stripped.startswith("====="):
                        break
                    if stripped.startswith("[") and stripped.endswith("]"):
                        grid_lines.append(stripped)
            if grid_lines:
                grid = []
                for line in grid_lines:
                    try:
                        row = ast.literal_eval(line)
                        if isinstance(row, list):
                            grid.append(row)
                    except:
                        continue
                if grid:
                    return grid
        except:
            pass
        return None

    # ----- Extract state features from a grid -----
    def extract_features(grid):
        rows = len(grid)
        cols = len(grid[0]) if rows else 0

        def cell_name(cell):
            if isinstance(cell, int):
                return int_to_name.get(cell, f"unknown_{cell}")
            return cell.lower()

        agent_pos = None
        blue_positions = []
        gray_positions = []
        red_positions = []

        for r in range(rows):
            row = grid[r]
            if len(row) != cols:
                continue
            for c in range(cols):
                colour = cell_name(row[c])
                if colour == "orange":
                    agent_pos = (r, c)
                elif colour == "blue":
                    blue_positions.append((r, c))
                elif colour == "gray":
                    gray_positions.append((r, c))
                elif colour == "red":
                    red_positions.append((r, c))

        # Blue phase from first blue cell
        blue_phase = -1
        if blue_positions:
            sample_col = blue_positions[0][1]
            if sample_col % 3 == 1:
                blue_phase = 0
            elif sample_col % 3 == 2:
                blue_phase = 1

        at_bottom = (agent_pos[0] == rows - 1) if agent_pos else False

        return {
            "rows": rows,
            "cols": cols,
            "agent": agent_pos,
            "blue_phase": blue_phase,
            "gray": gray_positions[0] if len(gray_positions) == 1 else (gray_positions if len(gray_positions) > 1 else None),
            "red": red_positions[0] if len(red_positions) == 1 else (red_positions if len(red_positions) > 1 else None),
            "at_bottom": at_bottom
        }

    # ----- Parse current grid -----
    current_grid = parse_grid(obs_current)
    if current_grid is None:
        return f"parse_fallback; {step_str}; grid_not_found"

    current_feats = extract_features(current_grid)

    # ----- Parse previous grid if available to infer action -----
    action_str = ""
    if len(observation_history) >= 2:
        prev_obs = observation_history[-2]
        prev_grid = parse_grid(prev_obs)
        if prev_grid is not None:
            prev_feats = extract_features(prev_grid)

            # Determine action based on differences
            # Rules:
            #   auto: agent row+1 (always), red existing row-1, bluePhase flip if final agent row % 5 == 3
            #   left/right: gray column -/+1 (if gray exists)
            #   up: if agent at bottom, wrap to row 0 and convert gray->red at same position (if gray exists)
            #   up without bottom: no effect (except auto)
            #   noop: only auto effects

            possible_actions = []

            # Auto effects: apply to both states
            # Agent row difference: always +1 due to auto, unless wrap from up
            agent_dr = current_feats["agent"][0] - prev_feats["agent"][0] if current_feats["agent"] and prev_feats["agent"] else None
            agent_dc = current_feats["agent"][1] - prev_feats["agent"][1] if current_feats["agent"] and prev_feats["agent"] else None

            # Gray status
            prev_gray = prev_feats["gray"]
            curr_gray = current_feats["gray"]
            gray_possible_left = False
            gray_possible_right = False

            if prev_gray is not None and curr_gray is not None:
                if isinstance(prev_gray, tuple) and isinstance(curr_gray, tuple):
                    if curr_gray[1] == prev_gray[1] - 1:
                        gray_possible_left = True
                    if curr_gray[1] == prev_gray[1] + 1:
                        gray_possible_right = True
            # Also handle case prev_gray exists and curr_gray is None -> possible up
            up_possible = False
            if prev_gray is not None and curr_gray is None:
                # up action would convert gray to red at same position
                # check if a red appears at the previous gray position
                if isinstance(prev_gray, tuple):
                    new_red = current_feats["red"]
                    if new_red is not None:
                        if isinstance(new_red, tuple) and new_red == prev_gray:
                            up_possible = True
                        elif isinstance(new_red, list) and prev_gray in new_red:
                            up_possible = True
            # Also up if agent wrapped? For simplicity, if agent row changed by more than 1? Not needed.

            # noop possible: only auto effects, no gray movement, no up conversion
            # Check if only auto changes occurred
            auto_only = True
            if prev_gray is not None and curr_gray is not None and not (gray_possible_left or gray_possible_right):
                auto_only = False
            if prev_gray is not None and curr_gray is None and not up_possible:
                auto_only = False
            # If no gray in both, then left/right/noop/up all have same effect (only auto)
            if prev_gray is None and curr_gray is None:
                # All actions except click and down? down not available? Actually down is in list but effect unknown? Assume down also same? We'll ignore down.
                auto_only = False  # mark ambiguous
                # This case: all of left,right,up,noop lead to same state.
                possible_actions = ["left", "right", "up", "noop"]

            if auto_only:
                possible_actions.append("noop")
            if gray_possible_left:
                possible_actions.append("left")
            if gray_possible_right:
                possible_actions.append("right")
            if up_possible:
                possible_actions.append("up")

            # If no gray and agent not at bottom, up has same effect as noop -> already covered by all four
            # If agent at bottom, up would wrap and convert gray, but gray may be absent -> different effect? Not needed.

            # Deduplicate
            possible_actions = list(dict.fromkeys(possible_actions))

            if len(possible_actions) == 1:
                action_str = f"prev_action:{possible_actions[0]}"
            else:
                action_str = f"prev_action:({'|'.join(sorted(possible_actions))})"

    # ----- Build feature summary -----
    rows = current_feats["rows"]
    cols = current_feats["cols"]
    agent = current_feats["agent"]
    blue_phase = current_feats["blue_phase"]
    gray = current_feats["gray"]
    red = current_feats["red"]
    at_bottom = current_feats["at_bottom"]

    # Rules string
    rules = (
        f"rules:grid{rows}x{cols};"
        "order=autoThenAction;"
        "auto:row+1,red-1-existing,blueFlip;"
        "left/right:grayCol-/+1;"
        "up:wrap+gray2red(noRedDecrement);"
        "noop:noEffect"
    )

    parts = [rules, step_str]

    # Agent
    if agent:
        parts.append(f"agent:({agent[0]},{agent[1]})")
    else:
        parts.append("agent:none")

    # Blue phase
    if blue_phase != -1:
        parts.append(f"bluePhase:{blue_phase}")
    else:
        parts.append("bluePhase:none")

    # Gray
    if gray is None:
        parts.append("gray:none")
    elif isinstance(gray, tuple):
        parts.append(f"gray:({gray[0]},{gray[1]})")
    else:
        coords = ",".join(f"({r},{c})" for r,c in gray)
        parts.append(f"gray:{coords}")

    # Red
    if red is None:
        parts.append("red:none")
    elif isinstance(red, tuple):
        parts.append(f"red:({red[0]},{red[1]})")
    else:
        coords = ",".join(f"({r},{c})" for r,c in red)
        parts.append(f"red:{coords}")

    parts.append(f"atBottom:{'true' if at_bottom else 'false'}")

    # Add action information
    if action_str:
        parts.append(action_str)

    result = "; ".join(parts)

    # Ensure non-empty and <2000 chars
    if not result.strip():
        result = f"fallback; {step_str}; no_features"
    if len(result) > 2000:
        result = result[:1997] + "..."

    return result

